import{_ as o,l as n,o as e,c as l,v as t,p as s,x as r,d as m,i as u,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"均值方差何时等于 EU","description":"","frontmatter":{"title":"均值方差何时等于 EU","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mean-variance-eu.md","filePath":"econ/mean-variance-eu.md","lastUpdated":1789023840000}'),A={name:"econ/mean-variance-eu.md"};function p(d,a,c,h,b,C){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="均值方差何时等于-eu" tabindex="-1">均值方差何时等于 EU <a class="header-anchor" href="#均值方差何时等于-eu" aria-label="Permalink to &quot;均值方差何时等于 EU&quot;">​</a></h1><div class="epigraph"><p>用均值与方差排序，只在效用是二次、或分布被这两个数字完全钉住时，才与期望效用是同一问题。</p><footer>—— 据 Markowitz, Portfolio Selection, Journal of Finance, 1952；对照 von Neumann–Morgenstern 表示</footer></div><p><a href="/econ/background-risk">上一课</a>（背景风险）。钉了 CARA / CRRA / DARA 的形状。本课不重写这些微分方程，也不把 \\(r_A\\) 再定义一遍。缺口是：资产配置文献常把目标直接写成 \\(V(\\mu,\\sigma)\\)。这在一般 \\(u\\) 与一般分布下并不等于 \\(\\mathbb{E}u\\)。必须标明两条——也几乎只有两条——使均值方差成为期望效用的充分统计，而不是另起一套偏好。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>vNM 的对象是整条分布。均值与方差是两个数字。若没有额外结构，两个分布可以 \\(\\mu\\)、\\(\\sigma\\) 相同而 \\(\\mathbb{E}u\\) 不同，也可以 \\(\\sigma\\) 更大但被所有凹 \\(u\\) 喜欢（偏度、支撑作怪）。缺口因此不是「要不要分散」，而是问：何时存在 \\(V\\)，使</p> \\[\\mathbb{E}\\,u(\\tilde w)=V\\bigl(\\mathbb{E}\\tilde w,\\mathrm{Var}(\\tilde w)\\bigr) \\]<p>对所考虑的菜单成立。答案是刀刃：要么 \\(u\\) 是二次，要么分布族被 \\((\\mu,\\sigma)\\) 参数化——正态是最常用的一员。Markowitz 的均值方差分析是这条刀刃上的算法，不是对 EU 的一般改写。本课不写组合实证，不把有效前沿拿去拟合收益。</p><p>二次效用 \\(u(w)=w-bw^2\\) 只依赖一、二阶矩，但 \\(r_A\\) 递增且存在餍足，与上一课的 DARA 工作假设冲突。故它是数学特例，不是主干偏好。</p><h3 id="正态加-cara-是另一条刀刃-不是二次" tabindex="-1">正态加 CARA 是另一条刀刃，不是二次 <a class="header-anchor" href="#正态加-cara-是另一条刀刃-不是二次" aria-label="Permalink to &quot;正态加 CARA 是另一条刀刃，不是二次&quot;">​</a></h3><p>若 \\(\\tilde w\\) 正态且 \\(u\\) 是 CARA，则 \\(\\mathbb{E}u\\) 是 \\(\\mu-\\tfrac12\\alpha\\sigma^2\\) 的单调变换。此时均值方差来自分布加形状，不是来自二次。CRRA 加对数正态在乘法冲击上有类似封闭解，但一般加法组合不是椭圆，EU 不能收成 \\((\\mu,\\sigma)\\)。不要把「正态」写成「任意钟形」。</p><p><span class="marginnote">椭圆分布族（正态是其中一员）使任意凹增的 \\(u\\) 在该族内的排序都是均值方差。族一离开，同一 \\(u\\) 会在偏度上分裂。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>检验两条路。路一：看 \\(u\\) 是否二次——只对没有餍足区的财富水平、且接受 IARA 时可用。路二：把菜单限制在正态（或椭圆）线性组合上，再选 CARA 或任意只通过 \\((\\mu,\\sigma)\\) 进入的 \\(V\\)。两条路都是对<strong>对象</strong>加约束，不是对独立性加约束。</p><p>若两条都不成立，均值方差可以与 EU 反向。后课<a href="/econ/stochastic-dominance">随机占优</a>会给出不指定 \\(u\\) 的偏序；方差更小既非 SOSD 的定义，也不是 MPS。本课先把「MV = EU」的许可证钉死，以免后课把 Markowitz 图当成一般风险厌恶。</p>',14)),(e(),s(E,null,{default:r(()=>[u(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E6%9C%9F%E6%9C%9B%E6%95%88%E7%94%A8%20E%20u%22%5D%20--%3E%20Q%5B%22u%20%E4%BA%8C%E6%AC%A1%22%5D%0A%20%20EU%20--%3E%20N%5B%22%E5%88%86%E5%B8%83%E7%94%B1%20%CE%BC%E3%80%81%CF%83%20%E9%92%89%E4%BD%8F%22%5D%0A%20%20Q%20--%3E%20MV%5B%22V(%CE%BC%2C%CF%83)%20%E5%90%88%E6%B3%95%22%5D%0A%20%20N%20--%3E%20MV%0A%20%20MV%20--%3E%20MK%5B%22Markowitz%EF%BC%9A%E8%AF%A5%E5%88%80%E5%88%83%E4%B8%8A%E7%9A%84%E7%AE%97%E6%B3%95%22%5D%0A%20%20EU%20--%3E%20NO%5B%22%E4%B8%80%E8%88%AC%20u%E3%80%81%E4%B8%80%E8%88%AC%E5%88%86%E5%B8%83%EF%BC%9AMV%20%E4%B8%8D%E5%A4%9F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>本课不引入 \\(\\beta\\)、市场组合或样本协方差。那些是定价课与量化栏的对象。这里只问表示何时塌成两个数字。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>二次的机制是泰勒在二阶截断且余项恒为零。正态的机制是分布被两个参数穷尽，任意积分 \\(\\mathbb{E}u\\) 都是 \\((\\mu,\\sigma)\\) 的函数。二者看起来像同一张图，来源不同：一个砍效用，一个砍世界。</p><p>与 CARA/CRRA 的接口：CARA+正态给出线性的均值方差权衡，绝对风险需求与财富无关，和上一课一致。CRRA+正态一般没有闭式 \\(V(\\mu,\\sigma)\\) 作为欧氏均值方差。把幂效用塞进 Markowitz 程序，是偷换了目标。</p><p><span class="marginnote">Markowitz 1952 自己把效用当背景动机，计算走的是 \\((\\mu,\\sigma)\\)。引用时不要把它写成拒绝 vNM，也不要写成 CAPM 实证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>近似：小风险下 Pratt 的局部溢价只用到方差，那是无穷小，不是有限菜单上的表示等式。大风险、偏度、跳跃，MV 排序可以误导。本课把「局部 ≈」与「全局 =」分开。</p><p>不完全市场、约束、非交易的劳动收入，会让可交易财富的边际分布不再正态，即使冲击原本是正态。刀刃更窄。也不要把有效前沿画成限价簿上的可成交组合：这里没有报价，只有给定分布族上的选择。</p><p>后课随机占优不依赖二次或正态。那是把本课的「两个数字不够」接下去：用整条分布的积分条件说话。</p><p>后课默认：均值方差等于 EU，仅当二次效用或（椭圆）分布被 \\((\\mu,\\sigma)\\) 参数化；Markowitz 是该特例的算法，不是一般风险偏好。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一般 \\(\\mathbb{E}u\\) 不能收成 \\(V(\\mu,\\sigma)\\)；二次 \\(u\\) 或正态/椭圆族是许可证。</li><li>二次带来 IARA 与餍足，与 DARA 主干不合。</li><li>CARA+正态是另一条合法刀刃，不等于二次。</li><li>本课不写组合实证；下一课用不指定 \\(u\\) 的占优处理一般分布。</li><li>出处：Markowitz, <em>Journal of Finance</em>, 1952；von Neumann and Morgenstern, 1944。</li></ul>',12))])}const g=o(A,[["render",p]]);export{f as __pageData,g as default};
